rows=[];csvrows=[]
for p in d['parts']:
    formal=0 if p['category']=='calibration' else p['quantity'];first=int(p['part'] in trialnames);later=max(0,formal-first)
    dims=' × '.join(f'{q:g}' for q in p['print_bbox_mm'])
    rows.append(f'<tr><td><code>{p["part"]}</code><small>{html.escape(p["label"])}</small></td><td>{formal}</td><td>{first}</td><td>{later}</td><td>{dims}</td></tr>')
